"""Relatório do backend PKIX: implementação testada versus evidência disponível."""
import html
from reportlab.platypus import PageBreak
from .pdf_layout import AnalysisPDF,pdf_styles,p,heading,table,WIDTH

LIMIT='Na amostra real, nenhum emissor ou âncora oficial novo foi obtido e nenhuma âncora foi selecionada. Os caminhos continuam inconclusivos e a revogação não é concluída. O sucesso dos testes com cadeias sintéticas não é resultado sobre as urnas.'
METHOD='O projeto passou a usar pyhanko-certvalidator 0.33.0 para construir e validar caminhos completos: assinaturas, vigência, restrições de CA, tamanho do caminho, nomes e extensões críticas sob o perfil configurado. Um adaptador explícito trata Ed521 e a codificação ECDSA usada nos certificados. Isso não é homologação do perfil TSE nem garantia de suporte a toda extensão ou política existente; casos não suportados falham sem aprovação.'
POLICY='As âncoras são entradas explícitas de um manifesto, com impressão digital e proveniência declarada. A lista TLS do sistema, um autoassinado ou um intermediário recebido não são usados como âncoras implicitamente. A declaração de origem num manifesto não autentica sozinha sua fonte: a seleção de confiança precisa de evidência documental e fica registrada.'
REV='A validação estrutural é executada com a verificação de revogação desativada e recebe um status próprio. Somente após um caminho conferir é exigida LCR para ponta e intermediários. Sem LCR adequada não há êxito de revogação. Rede automática, retroatividade de LCR e tolerância de relógio estão desativadas. LCR atuais não provam automaticamente o estado nas datas de outubro de 2026.'
TIME='Cada VSC é avaliado em três hipóteses de horário: data declarada tomada como UTC e limites correspondentes aos fusos UTC+14 e UTC−12. São hipóteses, não um carimbo autenticado. Mesmo êxito nos pontos testados não seria prova contínua de revogação durante todo o intervalo.'


def render(destination,summary,validations,units,attempts):
    esc=lambda x:html.escape(str(x))
    lead=f"A validação de caminho completo foi implementada e testada com material sintético. A execução real cobre {summary['section_turns']} unidades seção/turno, em {summary['scenarios']} cenários de horário, com {summary['anchors_supplied']} âncoras selecionadas."
    rows=[['Backend de caminho completo','Implementado','Testado com cadeias sintéticas ECDSA e Ed521'],['Revogação por LCR obrigatória','Implementada no backend','Testes sintéticos: válida, revogada e vencida'],['Fontes adicionais',str(summary['new_source_attempts'])+' tentativas','HTTP 403; nenhum objeto utilizável obtido'],['Amostra real',str(summary['section_turns'])+' unidades / '+str(summary['scenarios'])+' cenários','Caminhos inconclusivos sem âncora'],['Apontamento anterior de vigência',str(summary['issuer_period_outside'])+' ocorrências','Preservado; causa não confirmada']]
    unit_rows=[[r['uf'],r['municipality'],f'{r["zone"]}/{r["section"]}',r['turn'],r['scenarios'],r['paths_conferred'],'Sem âncora explícita'] for r in units.to_dict('records')]
    def tbl(head,body):return '<table><thead><tr>'+''.join('<th>'+esc(x)+'</th>' for x in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+esc(v)+'</td>' for v in row)+'</tr>' for row in body)+'</tbody></table>'
    resources=[('validacoes.csv','144 resultados do backend e motivos'),('unidades.csv','48 unidades e apontamento de vigência anterior'),('novas_tentativas.csv','11 tentativas complementares'),('politica_executada.json','Política, âncoras e alcance temporal'),('resumo.json','Síntese e versões'),('relatorio.pdf','PDF'),('../cadeia/relatorio.html','Conferência anterior preservada'),('../../../../docs/CAMINHO_PKIX.md','Método e reprodução')]
    page=f'''<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Validação de caminho PKIX — 2026</title><style>body{{font:17px/1.65 system-ui;color:#183447;background:#f1f5f7;margin:0}}main{{max-width:1100px;margin:auto;background:white;padding:2rem}}h1{{line-height:1.2}}h2{{color:#12677a;margin-top:2rem}}table{{border-collapse:collapse;width:100%;font-size:.88rem}}td,th{{padding:.5rem;text-align:left;border-bottom:1px solid #ccd9df}}th{{background:#edf4f7}}.limit{{background:#fff8e9;border-left:5px solid #bd7427;padding:1rem}}.scroll{{overflow:auto}}a{{color:#075f8a}}</style><main>
<p>Etapa 5 · implementação de caminho completo e política de revogação</p><h1>Validador de caminho implementado; conclusão real continua dependente das fontes oficiais</h1><p>{esc(lead)}</p><p class="limit">{esc(LIMIT)}</p><div class="scroll">{tbl(['Frente','Código / universo','Execução e limite'],rows)}</div>
<h2>O que mudou</h2><p>{esc(METHOD)}</p><p>{esc(POLICY)}</p><p>{esc(REV)}</p><p>{esc(TIME)}</p>
<h2>Testes controlados e limites</h2><p>Foram testados caminhos completos com raiz explícita, intermediário, ponta e LCR; um emissor e uma LCR Ed521 sintéticos usam a referência Noble. Os testes rejeitam ausência de âncora, assinatura errada, intermediário vencido, violação de pathLen, NameConstraints, extensão crítica desconhecida, LCR vencida e certificado revogado. Nenhuma semente ou chave de teste corresponde às urnas.</p>
<h2>Pesquisa complementar</h2><p>Foram consultadas seis rotas candidatas de certificados sob a base HTTPS /dpc/ identificada na extração da página e cinco rotas candidatas /lcr/. As {summary['new_source_attempts']} consultas retornaram HTTP 403, com TLS verificado. As {summary['previous_source_attempts']} tentativas anteriores permanecem preservadas; não são contadas como novas. Raízes ICP-Brasil encontradas na busca não foram adotadas como substitutas da PKI das urnas.</p>
<h2>Resultado por unidade</h2><p>Zero caminhos conferidos significa falta de conclusão com as fontes fornecidas, não demonstração de fraude ou de ausência de irregularidades. Os 14 apontamentos anteriores sobre a vigência do candidato disponível AC URNA continuam pendentes, sem mudança de causa ou classificação.</p><div class="scroll">{tbl(['UF','Município TSE','Zona/seção','Turno','Cenários','Caminhos conferidos','Situação'],unit_rows)}</div>
<h2>Fontes e reprodução</h2><ul>{''.join('<li><a href="'+url+'">'+esc(label)+'</a></li>' for url,label in resources)}</ul><p>Backend: <a href="https://pypi.org/project/pyhanko-certvalidator/0.33.0/">pyhanko-certvalidator 0.33.0</a>; referência de caminho: <a href="https://www.rfc-editor.org/rfc/rfc5280.html">RFC 5280</a>. O adaptador e a configuração local não têm homologação ou auditoria criptográfica independente.</p><h2>O que ainda impede concluir o item 1</h2><p>Obter os emissores faltantes e âncoras com origem oficial verificável, selecionar a confiança de modo documentado e obter LCR históricas adequadas. Não foram enviados pedidos ou mensagens a terceiros. OCSP, CEPESC, layout oficial, logs e BU independente permanecem frentes distintas.</p></main></html>'''
    (destination/'relatorio.html').write_text(page,encoding='utf8')
    styles=pdf_styles();story=[heading('Validação de caminho PKIX — 2026','inicio',styles),p(lead,styles,'Deck'),p(LIMIT,styles),table(['Frente','Código / universo','Execução e limite'],rows,[WIDTH*.29,WIDTH*.23,WIDTH*.48],styles,small=True),p('São 144 tentativas em três hipóteses por unidade, não 144 urnas. Resultados positivos em material sintético não são atribuídos aos certificados da amostra. Os resultados anteriores permanecem preservados.',styles),PageBreak(),heading('Método, política e fontes','metodo',styles),p(METHOD,styles),p(POLICY,styles),p(REV,styles),p(TIME,styles),p('Os testes controlados cobrem cadeias completas ECDSA e Ed521 e LCR, além de corrupção, revogação, restrições e ausência de confiança implícita. Foram feitas 11 consultas complementares sem documento utilizável obtido. A origem e o conteúdo das 21 tentativas anteriores permanecem intactos.',styles),p('Para concluir o item 1, faltam os emissores/âncoras com proveniência oficial e LCR históricas adequadas. Fontes, política e comandos em docs/CAMINHO_PKIX.md e no HTML.',styles)]
    for offset in range(0,len(unit_rows),16):
        story.extend([PageBreak(),heading(f'Unidades {offset+1}–{min(offset+16,len(unit_rows))}','unidades-'+str(offset),styles),p('Z/S = zona/seção; Tº = turno. Zero caminhos conferidos é inconclusivo sem âncora, não uma conclusão sobre regularidade eleitoral. Cada unidade foi avaliada em três hipóteses de horário.',styles,'Small'),table(['UF','Mun. TSE','Z/S','Tº','Cenários','Conferidos','Situação'],unit_rows[offset:offset+16],[WIDTH*x for x in (.06,.14,.13,.07,.14,.16,.30)],styles,small=True)])
    AnalysisPDF(destination/'relatorio.pdf',title='Validação de caminho PKIX — 2026',styles=styles).build(story)
